#!/usr/bin/env python3
"""Standalone five-seed fullerene benchmark built directly from the raw dataset.

Models
------
1. physics_guided_residual_gnn: corrected implementation embedded in this file.
2. FullereneNet: official model implementation embedded in this file.
3. Matformer: official comparison implementation embedded in this file.

This single file does not import gap2.py, clone a repository, or load another model script.
It reads the label CSV and GJF geometry tree directly, creates a validated cache
automatically, uses eV targets, disables post-processing, and applies the
same sample indices for every model at a given seed.  It reports per-seed
metrics and mean +/- sample standard deviation.  It can additionally export
the exact splits to the official ALIGNN folder/CLI format.

Official FullereneNet repository:
https://github.com/Liu-Group-UF/FullereneNet (MIT, v1.0.0 archived at Zenodo
10.5281/zenodo.17426461).
"""

from __future__ import annotations

import argparse
import base64
from concurrent.futures import ThreadPoolExecutor
import csv
import gc
import hashlib
import json
import os
from pathlib import Path
import random
import re
import sys
import types
import zlib
from typing import Any

import numpy as np
import pandas as pd
import torch
from sklearn.metrics import mean_absolute_error, mean_squared_error, r2_score


TARGET_UNIT = "eV"
DEFAULT_SEEDS = (2024, 2025, 2026, 2027, 2028)
FULLERENENET_URL = "https://github.com/Liu-Group-UF/FullereneNet.git"

OFFICIAL_COMMIT = "5039e89ce75d83bd7060ab84618cf636b088e3b0"
_EMBEDDED_GAP2 = ""
_EMBEDDED_FULLERENENET = ""
_EMBEDDED_MATFORMER = ""


def _load_embedded_module(name: str, encoded_source: str):
    module = types.ModuleType(name)
    module.__file__ = f"<{name}>"
    module.__package__ = ""
    source_text = zlib.decompress(base64.b64decode(encoded_source)).decode("utf-8")
    # PyTorch Geometric's Inspector resolves type annotations through
    # sys.modules, just like Python's normal import machinery does.
    sys.modules[name] = module
    try:
        exec(compile(source_text, module.__file__, "exec"), module.__dict__)
    except Exception:
        sys.modules.pop(name, None)
        raise
    return module


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--project-dir", type=Path, default=Path.cwd(),
                        help="Dataset directory containing the CSV and geometry folder.")
    parser.add_argument("--csv", type=Path, default=Path("data/dataset.csv"),
                        help="Label table with ID, AtomCount and Gap columns.")
    parser.add_argument("--geometry-root", type=Path, default=Path("data/structures"),
                        help="Root directory containing the GJF geometry files.")
    parser.add_argument("--gap-unit", choices=("hartree", "eV"), default="hartree",
                        help="Unit of the Gap column in the source CSV.")
    parser.add_argument("--cache", type=Path, default=None,
                        help="Optional generated cache path; never required in advance.")
    parser.add_argument("--rebuild-cache", action="store_true",
                        help="Ignore generated caches and rebuild directly from CSV/GJF files.")
    parser.add_argument("--preprocess-workers", type=int, default=4)
    parser.add_argument("--output-dir", type=Path,
                        default=Path("results/graph_benchmarks"))
    parser.add_argument("--seeds", nargs="+", type=int, default=list(DEFAULT_SEEDS))
    parser.add_argument("--protocols", nargs="+", choices=("random", "group"),
                        default=("random", "group"))
    parser.add_argument("--models", nargs="+",
                        choices=("proposed", "fullerenenet", "matformer"),
                        default=("proposed", "fullerenenet", "matformer"))
    parser.add_argument("--pyg-epochs", type=int, default=300)
    parser.add_argument("--pyg-patience", type=int, default=70)
    parser.add_argument("--batch-size", type=int, default=32)
    parser.add_argument("--lr", type=float, default=5e-4)
    parser.add_argument("--weight-decay", type=float, default=0.0)
    parser.add_argument("--resume", action="store_true",
                        help="Skip completed model/protocol/seed runs.")
    parser.add_argument("--export-alignn", action="store_true",
                        help="Export shared XYZ files, id_prop.csv, configs and commands for official ALIGNN.")
    parser.add_argument("--alignn-epochs", type=int, default=300)
    return parser.parse_args()


def load_gap2(project_dir: Path):
    # Kept under the historical function name so the audited training code below
    # remains unchanged; the implementation is embedded in this single file.
    return _load_embedded_module("embedded_clean_gap2", _EMBEDDED_GAP2)


def _resolve_under(base: Path, value: Path) -> Path:
    return value.resolve() if value.is_absolute() else (base / value).resolve()


def scan_raw_dataset(gap2, csv_path: Path, geometry_root: Path):
    if not csv_path.is_file():
        raise FileNotFoundError(f"Dataset CSV was not found: {csv_path}")
    if not geometry_root.is_dir():
        raise FileNotFoundError(f"Geometry root was not found: {geometry_root}")

    frame = pd.read_csv(csv_path).copy()
    required = {"ID", "AtomCount", "Gap"}
    missing = required - set(frame.columns)
    if missing:
        raise ValueError(f"CSV is missing required columns: {sorted(missing)}")
    frame["ID"] = pd.to_numeric(frame["ID"], errors="raise").astype(int)
    frame["AtomCount"] = pd.to_numeric(frame["AtomCount"], errors="raise").astype(int)
    frame["Gap"] = pd.to_numeric(frame["Gap"], errors="raise")
    if frame[["ID", "AtomCount", "Gap"]].isna().any().any():
        raise ValueError("CSV contains missing ID, AtomCount or Gap values.")
    if frame.duplicated(["AtomCount", "ID"]).any():
        duplicates = frame.loc[
            frame.duplicated(["AtomCount", "ID"], keep=False), ["AtomCount", "ID"]
        ]
        raise ValueError(
            "CSV contains duplicate (AtomCount, ID) keys: "
            f"{duplicates.head(10).to_dict('records')}"
        )

    file_index = {}
    for path in sorted(geometry_root.rglob("*")):
        if not path.is_file() or path.suffix.lower() != ".gjf":
            continue
        relative = path.relative_to(geometry_root)
        flat_match = re.fullmatch(r"C(\d+)_(\d+)\.gjf", path.name, re.IGNORECASE)
        if len(relative.parts) == 2 and flat_match:
            key = (int(flat_match.group(1)), int(flat_match.group(2)))
            if relative.parent.name.lower() != f"c{key[0]}":
                raise ValueError(f"Cage-size directory does not match filename: {path}")
        else:
            key = gap2.parse_fullerene_file_key(str(path))
        if key in file_index:
            raise RuntimeError(
                f"Duplicate geometry for (AtomCount, ID)={key}: "
                f"{file_index[key]} and {path}"
            )
        file_index[key] = path

    source_keys = [(int(row.AtomCount), int(row.ID)) for row in frame.itertuples(index=False)]
    missing_files = sorted(set(source_keys) - set(file_index))
    if missing_files:
        raise RuntimeError(
            f"Missing {len(missing_files)} geometries required by the CSV. "
            f"First missing keys: {missing_files[:10]}"
        )

    digest = hashlib.sha256(csv_path.read_bytes())
    for key in source_keys:
        path = file_index[key]
        stat = path.stat()
        relative = path.relative_to(geometry_root).as_posix()
        digest.update(f"{key[0]}|{key[1]}|{relative}|{stat.st_size}|{stat.st_mtime_ns}\n".encode())
    return frame, file_index, source_keys, digest.hexdigest()


def load_or_build_raw_dataset(gap2, csv_path: Path, geometry_root: Path,
                              cache_path: Path, gap_unit: str,
                              workers: int, rebuild: bool):
    frame, file_index, source_keys, source_fingerprint = scan_raw_dataset(
        gap2, csv_path, geometry_root
    )
    if cache_path.exists() and not rebuild:
        try:
            cache = gap2.safe_torch_load(str(cache_path), map_location="cpu")
            data = cache.get("data", []) if isinstance(cache, dict) else []
            valid = (
                cache.get("schema_version") == gap2.CACHE_SCHEMA_VERSION
                and cache.get("target_unit") == TARGET_UNIT
                and cache.get("source_fingerprint") == source_fingerprint
                and len(data) == len(frame)
                and all(
                    int(item["N"]) == int(item["intended_N"])
                    and item.get("unit") == TARGET_UNIT
                    for item in data
                )
            )
            if valid:
                print(f"Loading validated generated cache: {cache_path}")
                return data, source_fingerprint
            print("Generated cache does not match the raw dataset; rebuilding it.")
        except Exception as exc:
            print(f"Could not validate generated cache ({exc}); rebuilding it.")

    factor = gap2.HARTREE_TO_EV if gap_unit == "hartree" else 1.0
    tasks = [
        (str(file_index[(int(row.AtomCount), int(row.ID))]),
         float(row.Gap) * factor, int(row.AtomCount), int(row.ID))
        for row in frame.itertuples(index=False)
    ]
    print(f"Building validated graphs directly from {len(tasks)} CSV/GJF pairs...")
    workers = max(1, int(workers))
    if workers == 1:
        results = [gap2.process_single_file(task) for task in tasks]
    else:
        # Threads avoid dynamic-module pickling failures while retaining parallel I/O.
        with ThreadPoolExecutor(max_workers=workers) as executor:
            results = list(executor.map(gap2.process_single_file, tasks))

    errors = []
    data = []
    for task, result in zip(tasks, results):
        if result is None:
            errors.append({"source_path": task[0], "error": "worker returned no result"})
        elif "error" in result:
            errors.append(result)
        else:
            data.append(result)
    if errors:
        error_path = cache_path.with_name("preprocess_errors.json")
        error_path.write_text(json.dumps(errors, ensure_ascii=False, indent=2), encoding="utf-8")
        raise RuntimeError(
            f"Feature extraction failed for {len(errors)} samples; details: {error_path}"
        )

    expected = set(source_keys)
    processed = {(int(item["intended_N"]), int(item["sample_id"])) for item in data}
    if len(data) != len(frame) or processed != expected:
        raise RuntimeError("Processed graphs are not a one-to-one match with the source CSV.")
    if any(int(item["N"]) != int(item["intended_N"]) for item in data):
        raise RuntimeError("At least one geometry size differs from the CSV AtomCount.")
    if any(item.get("unit") != TARGET_UNIT for item in data):
        raise RuntimeError("At least one processed target is not in eV.")

    cache_path.parent.mkdir(parents=True, exist_ok=True)
    torch.save({
        "schema_version": gap2.CACHE_SCHEMA_VERSION,
        "target_unit": TARGET_UNIT,
        "source_csv": str(csv_path),
        "geometry_root": str(geometry_root),
        "source_fingerprint": source_fingerprint,
        "data": data,
        "groups": [gap2.split_for_atom_count(int(item["intended_N"])) for item in data],
    }, cache_path)
    print(f"Validated generated cache saved to: {cache_path}")
    return data, source_fingerprint


def load_validated_cache(gap2, cache_path: Path) -> list[dict[str, Any]]:
    cache = gap2.safe_torch_load(str(cache_path), map_location="cpu")
    if not isinstance(cache, dict):
        raise RuntimeError("Cache must be a dictionary created by corrected gap2.py.")
    if cache.get("schema_version") != gap2.CACHE_SCHEMA_VERSION:
        raise RuntimeError("Obsolete cache schema. Run corrected gap2.py first.")
    if cache.get("target_unit") != TARGET_UNIT:
        raise RuntimeError("Cache target unit is not eV.")
    data = cache.get("data", [])
    required = {
        "N", "intended_N", "sample_id", "source_path", "unit", "y_target",
        "coords", "adj", "node_feat", "e_ring",
    }
    keys = []
    for item in data:
        missing = required - set(item)
        if missing:
            raise RuntimeError(f"Cached sample is missing {sorted(missing)}")
        if int(item["N"]) != int(item["intended_N"]):
            raise RuntimeError("Label/geometry atom-count mismatch remains in cache.")
        if item["unit"] != TARGET_UNIT:
            raise RuntimeError("A cached sample is not in eV.")
        keys.append((int(item["intended_N"]), int(item["sample_id"])))
    if not data or len(keys) != len(set(keys)):
        raise RuntimeError("Cache is empty or contains duplicate sample keys.")
    return data


def seed_everything(seed: int) -> None:
    os.environ["PYTHONHASHSEED"] = str(seed)
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)
    if torch.cuda.is_available():
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False


def torch_load_compatible(path: Path, map_location="cpu"):
    try:
        return torch.load(path, map_location=map_location, weights_only=False)
    except TypeError:
        return torch.load(path, map_location=map_location)


def split_indices(data, protocol: str, seed: int) -> dict[str, np.ndarray]:
    if protocol == "random":
        permutation = np.random.RandomState(seed).permutation(len(data))
        n_train = int(0.8 * len(data))
        n_val = int(0.1 * len(data))
        result = {
            "train": permutation[:n_train],
            "val": permutation[n_train:n_train + n_val],
            "test": permutation[n_train + n_val:],
        }
    else:
        result_list = {"train": [], "val": [], "test": []}
        for index, item in enumerate(data):
            n_atoms = int(item["intended_N"])
            if 20 <= n_atoms <= 56:
                result_list["train"].append(index)
            elif n_atoms in (58, 60):
                result_list["val"].append(index)
            elif 70 <= n_atoms <= 100:
                result_list["test"].append(index)
            else:
                raise RuntimeError(f"C{n_atoms} is outside the declared group protocol.")
        result = {k: np.asarray(v, dtype=int) for k, v in result_list.items()}
    merged = np.concatenate(list(result.values()))
    if len(merged) != len(data) or len(np.unique(merged)) != len(data):
        raise RuntimeError("Split is incomplete or overlapping.")
    return result


def write_manifest(data, indices, protocol: str, seed: int, path: Path) -> None:
    split_by_index = {}
    for split_name, values in indices.items():
        for index in values:
            split_by_index[int(index)] = split_name
    rows = []
    for index, item in enumerate(data):
        rows.append({
            "row_index": index,
            "sample_id": int(item["sample_id"]),
            "intended_N": int(item["intended_N"]),
            "geometry_N": int(item["N"]),
            "split": split_by_index[index],
            "protocol": protocol,
            "seed": seed,
            "unit": item["unit"],
            "source_path": item["source_path"],
        })
    frame = pd.DataFrame(rows)
    frame.to_csv(path, index=False)
    digest = hashlib.sha256(
        frame[["sample_id", "intended_N", "split"]].to_csv(index=False).encode("utf-8")
    ).hexdigest()
    path.with_suffix(".sha256").write_text(digest + "\n", encoding="utf-8")


def safe_r2(y_true, y_pred) -> float:
    y_true = np.asarray(y_true, dtype=float)
    y_pred = np.asarray(y_pred, dtype=float)
    if len(y_true) < 2 or np.isclose(np.var(y_true), 0.0):
        return float("nan")
    return float(r2_score(y_true, y_pred))


def metric_row(model: str, protocol: str, seed: int, split: str, y_true, y_pred) -> dict[str, Any]:
    y_true = np.asarray(y_true, dtype=float)
    y_pred = np.asarray(y_pred, dtype=float)
    error = y_pred - y_true
    return {
        "model": model,
        "protocol": protocol,
        "seed": seed,
        "split": split,
        "count": int(len(y_true)),
        "unit": TARGET_UNIT,
        "r2": safe_r2(y_true, y_pred),
        "mae": float(mean_absolute_error(y_true, y_pred)),
        "rmse": float(np.sqrt(mean_squared_error(y_true, y_pred))),
        "bias_pred_minus_true": float(np.mean(error)),
    }


def read_completed_metrics(path: Path, model: str, protocol: str, seed: int):
    if not path.exists():
        return None
    try:
        frame = pd.read_csv(path)
        required = {
            "model", "protocol", "seed", "split", "count", "unit",
            "r2", "mae", "rmse", "bias_pred_minus_true",
        }
        if not required.issubset(frame.columns) or len(frame) != 3:
            return None
        if set(frame["split"]) != {"train", "val", "test"}:
            return None
        if set(frame["model"].astype(str)) != {model}:
            return None
        if set(frame["protocol"].astype(str)) != {protocol}:
            return None
        if set(frame["seed"].astype(int)) != {int(seed)}:
            return None
        if set(frame["unit"].astype(str)) != {TARGET_UNIT}:
            return None
        numeric = frame[["count", "r2", "mae", "rmse", "bias_pred_minus_true"]].apply(
            pd.to_numeric, errors="coerce"
        )
        if numeric.isna().any().any() or (numeric["count"] <= 0).any():
            return None
        return frame
    except Exception:
        return None


def validation_selection_score(protocol: str, atom_counts, y_true, y_pred) -> float:
    if protocol == "random":
        return safe_r2(y_true, y_pred)
    atom_counts = np.asarray(atom_counts, dtype=int)
    scores = []
    for size in (58, 60):
        mask = atom_counts == size
        score = safe_r2(np.asarray(y_true)[mask], np.asarray(y_pred)[mask])
        scores.append(-1.0 if np.isnan(score) else score)
    mean_score = float(np.mean(scores))
    return min(mean_score, -1.0) if any(x <= 0 for x in scores) else mean_score


FULLERENENET_EDGE_MAP = {
    "HHHH": 0, "HHPH": 1, "PHHH": 1, "HPHH": 2, "HHHP": 2,
    "HPPH": 3, "PHHP": 3, "PPHH": 3, "HHPP": 3, "PHPH": 4,
    "HPHP": 5, "HPPP": 6, "PPHP": 6, "PPPH": 7, "PHPP": 7,
    "PPPP": 8,
}


def other_neighbors(adjacency: np.ndarray, node: int, excluded: int) -> tuple[int, int]:
    values = [int(x) for x in np.flatnonzero(adjacency[node] > 0) if int(x) != excluded]
    if len(values) != 2:
        raise RuntimeError("FullereneNet features require a three-regular graph.")
    return values[0], values[1]


def official_edge_type(adjacency: np.ndarray, distances: np.ndarray, node_0: int, node_1: int) -> str:
    node_a, node_b = other_neighbors(adjacency, node_0, node_1)
    node_c, node_d = other_neighbors(adjacency, node_1, node_0)
    if distances[node_a, node_c] > distances[node_a, node_d]:
        node_c, node_d = node_d, node_c

    node_a1, node_a2 = other_neighbors(adjacency, node_a, node_0)
    if distances[node_a1, node_c] > distances[node_a2, node_c]:
        node_a1, node_a2 = node_a2, node_a1
    node_c1, node_c2 = other_neighbors(adjacency, node_c, node_1)
    if distances[node_c1, node_a] > distances[node_c2, node_a]:
        node_c1, node_c2 = node_c2, node_c1
    first = "P" if node_a1 == node_c1 else "H"

    node_d1, node_d2 = other_neighbors(adjacency, node_d, node_1)
    if distances[node_d1, node_b] > distances[node_d2, node_b]:
        node_d1, node_d2 = node_d2, node_d1
    node_c2a, node_c2b = other_neighbors(adjacency, node_c2, node_c)
    second = "P" if node_d2 in (node_c2a, node_c2b) else "H"

    node_b1, node_b2 = other_neighbors(adjacency, node_b, node_0)
    if distances[node_b1, node_d] > distances[node_b2, node_d]:
        node_b1, node_b2 = node_b2, node_b1
    third = "P" if node_b1 == node_d1 else "H"
    node_b2a, node_b2b = other_neighbors(adjacency, node_b2, node_b)
    fourth = "P" if node_a2 in (node_b2a, node_b2b) else "H"
    return first + second + third + fourth


def make_pyg_graphs(data, output_dir: Path, dataset_fingerprint: str):
    try:
        from torch_geometric.data import Data
    except ImportError as exc:
        raise RuntimeError(
            "FullereneNet/Matformer require torch-geometric. Install it in the GPU environment."
        ) from exc

    feature_cache = output_dir / "adapted_pyg_graphs_v1.pt"
    if feature_cache.exists():
        try:
            payload = torch_load_compatible(feature_cache, map_location="cpu")
            valid = (
                payload.get("schema") == 2
                and payload.get("dataset_fingerprint") == dataset_fingerprint
                and len(payload.get("fullerenenet", [])) == len(data)
                and len(payload.get("matformer", [])) == len(data)
            )
            if valid:
                print(f"Loading validated graph-model cache: {feature_cache}")
                return payload["fullerenenet"], payload["matformer"]
            print("Graph-model cache is stale; rebuilding it from validated raw data.")
        except Exception as exc:
            print(f"Could not validate graph-model cache ({exc}); rebuilding it.")

    fullerene_graphs, matformer_graphs = [], []
    centers = np.linspace(0.5, 3.0, 19, dtype=np.float32)
    width = float(centers[1] - centers[0])
    for row_index, item in enumerate(data):
        adjacency = np.asarray(item["adj"], dtype=np.float32)
        coordinates = np.asarray(item["coords"], dtype=np.float32)
        src, dst = np.nonzero(adjacency > 0)
        edge_index = torch.tensor(np.stack([src, dst]), dtype=torch.long)

        n5 = np.rint(np.asarray(item["node_feat"])[:, 0] * 3.0).astype(int)
        if np.any((n5 < 0) | (n5 > 3)):
            raise RuntimeError("Invalid pentagon count in validated cache.")
        node_topology = np.eye(4, dtype=np.float32)[3 - n5]
        delta = coordinates[:, None, :] - coordinates[None, :, :]
        distances = np.linalg.norm(delta, axis=-1)
        edge_topology = np.zeros((len(src), 9), dtype=np.float32)
        for edge_id, (u, v) in enumerate(zip(src, dst)):
            key = official_edge_type(adjacency, distances, int(u), int(v))
            if key not in FULLERENENET_EDGE_MAP:
                raise RuntimeError(f"Unsupported official FullereneNet edge type: {key}")
            edge_topology[edge_id, FULLERENENET_EDGE_MAP[key]] = 1.0

        y = torch.tensor([float(item["y_target"])], dtype=torch.float32)
        fullerene_graphs.append(Data(
            x=torch.tensor(node_topology), edge_index=edge_index,
            edge_attr=torch.tensor(edge_topology), y=y,
            row_index=torch.tensor([row_index], dtype=torch.long),
        ))

        carbon_features = np.zeros((len(coordinates), 92), dtype=np.float32)
        carbon_features[:, 5] = 1.0
        bond_distances = distances[src, dst].astype(np.float32)
        edge_rbf = np.exp(-0.5 * ((bond_distances[:, None] - centers[None, :]) / width) ** 2)
        matformer_graphs.append(Data(
            x=torch.tensor(carbon_features), edge_index=edge_index,
            edge_attr=torch.tensor(edge_rbf, dtype=torch.float32), y=y,
            row_index=torch.tensor([row_index], dtype=torch.long),
        ))

    torch.save({
        "schema": 2,
        "dataset_fingerprint": dataset_fingerprint,
        "fullerenenet": fullerene_graphs,
        "matformer": matformer_graphs,
        "provenance": {
            "fullerenenet_node": "official four-class adjacent-pentagon one-hot",
            "fullerenenet_edge": "official nine-class four-ring edge environment",
            "matformer_node": "92-d carbon atomic-number one-hot",
            "matformer_edge": "19 Gaussian bond-distance functions over 0.5-3.0 Angstrom",
        },
    }, feature_cache)
    return fullerene_graphs, matformer_graphs


def predict_pyg(model, graphs, indices, loader_class, batch_size, device, target_mean, target_std):
    # Do not read ``batch.row_index`` here.  PyG treats attribute names that
    # contain "index" as graph indices and increments them while batching.
    # The evaluation loader is not shuffled, so the original dataset indices
    # can be recovered safely from the input order instead.
    ordered_indices = [int(i) for i in indices]
    selected_graphs = [graphs[i] for i in ordered_indices]
    loader = loader_class(selected_graphs, batch_size=batch_size, shuffle=False)
    model.eval()
    rows = []
    cursor = 0
    with torch.no_grad():
        for batch in loader:
            batch = batch.to(device)
            pred = model(batch).reshape(-1) * target_std + target_mean
            true = batch.y.reshape(-1)

            if pred.numel() != true.numel():
                raise RuntimeError(
                    f"Prediction count mismatch inside batch: pred={pred.numel()}, true={true.numel()}."
                )
            current_batch_size = int(true.numel())
            row_ids = ordered_indices[cursor:cursor + current_batch_size]
            cursor += current_batch_size
            if len(row_ids) != current_batch_size:
                raise RuntimeError(
                    "Evaluation loader produced more samples than the supplied dataset indices."
                )

            for row_index, y_true, y_pred in zip(row_ids, true.cpu(), pred.cpu()):
                rows.append((int(row_index), float(y_true), float(y_pred)))

    if cursor != len(ordered_indices):
        raise RuntimeError(
            f"Prediction count mismatch: expected {len(ordered_indices)}, got {cursor}."
        )
    return rows


def run_official_pyg_model(model_key: str, model_class, graphs, data, indices,
                           protocol: str, seed: int, run_dir: Path, args,
                           official_commit: str) -> pd.DataFrame:
    metrics_path = run_dir / "metrics.csv"
    completed = read_completed_metrics(metrics_path, model_key, protocol, seed)
    if args.resume and completed is not None:
        print(f"Skipping completed run: {model_key}/{protocol}/seed_{seed}")
        return completed
    from torch_geometric.loader import DataLoader

    run_dir.mkdir(parents=True, exist_ok=True)
    seed_everything(seed)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    if model_key == "fullerenenet":
        model = model_class(atom_input_features=4, node_fea=64, edge_fea=9,
                            conv_layers=3, hidden_layer=128, heads=4, dropout=0.0)
    else:
        model = model_class(atom_input_features=92, node_fea=64, edge_fea=19,
                            conv_layers=3, hidden_layer=128, heads=4)
    model.to(device)

    train_idx = indices["train"]
    train_y = np.asarray([float(data[int(i)]["y_target"]) for i in train_idx])
    expected_target_mean = float(train_y.mean())
    expected_target_std = float(max(train_y.std(), 1e-8))
    checkpoint_path = run_dir / "best_model.pt"
    history_path = run_dir / "training_history.csv"
    # ``training_history.csv`` is written only after the training loop finishes.
    # Reuse a checkpoint for evaluation only when both files exist; a checkpoint
    # from a job killed mid-training must not be mistaken for a completed fit.
    recover_for_evaluation = (
        args.resume and checkpoint_path.exists() and history_path.exists()
    )

    if recover_for_evaluation:
        checkpoint = torch_load_compatible(checkpoint_path, map_location=device)
        checkpoint_seed = int(checkpoint.get("seed", seed))
        checkpoint_protocol = str(checkpoint.get("protocol", protocol))
        checkpoint_commit = str(checkpoint.get("official_repo_commit", official_commit))
        if checkpoint_seed != int(seed) or checkpoint_protocol != protocol:
            raise RuntimeError(
                "Checkpoint metadata does not match the requested run: "
                f"checkpoint seed/protocol={checkpoint_seed}/{checkpoint_protocol}, "
                f"requested={seed}/{protocol}."
            )
        if checkpoint_commit != official_commit:
            raise RuntimeError(
                "Checkpoint repository commit does not match the embedded official model: "
                f"checkpoint={checkpoint_commit}, current={official_commit}."
            )

        target_mean = float(checkpoint["target_mean"])
        target_std = float(checkpoint["target_std"])
        if not np.isclose(target_mean, expected_target_mean, rtol=0.0, atol=1e-7):
            raise RuntimeError(
                "Checkpoint target mean does not match the current training split: "
                f"checkpoint={target_mean}, current={expected_target_mean}."
            )
        if not np.isclose(target_std, expected_target_std, rtol=0.0, atol=1e-7):
            raise RuntimeError(
                "Checkpoint target standard deviation does not match the current training split: "
                f"checkpoint={target_std}, current={expected_target_std}."
            )

        best_epoch = int(checkpoint.get("epoch", 0))
        best_score = float(checkpoint.get("selection_score", np.nan))
        model.load_state_dict(checkpoint["model_state_dict"])
        print(
            f"Resuming incomplete run from checkpoint for evaluation only: "
            f"{model_key}/{protocol}/seed_{seed} "
            f"(best_epoch={best_epoch}, best_score={best_score:.6f})"
        )
    else:
        target_mean = expected_target_mean
        target_std = expected_target_std
        generator = torch.Generator().manual_seed(seed)
        train_loader = DataLoader(
            [graphs[int(i)] for i in train_idx],
            batch_size=args.batch_size,
            shuffle=True,
            generator=generator,
        )
        optimizer = torch.optim.Adam(
            model.parameters(), lr=args.lr, weight_decay=args.weight_decay
        )
        scheduler = torch.optim.lr_scheduler.OneCycleLR(
            optimizer,
            max_lr=args.lr,
            steps_per_epoch=len(train_loader),
            epochs=args.pyg_epochs,
        )

        best_score = -np.inf
        best_epoch = 0
        stale_epochs = 0
        history = []
        val_atom_counts = np.asarray(
            [int(data[int(i)]["intended_N"]) for i in indices["val"]]
        )
        for epoch in range(1, args.pyg_epochs + 1):
            model.train()
            total_loss, batches = 0.0, 0
            for batch in train_loader:
                batch = batch.to(device)
                optimizer.zero_grad()
                pred_norm = model(batch).reshape(-1)
                target_norm = (batch.y.reshape(-1) - target_mean) / target_std
                loss = torch.nn.functional.mse_loss(pred_norm, target_norm)
                loss.backward()
                torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
                optimizer.step()
                scheduler.step()
                total_loss += float(loss.detach().cpu())
                batches += 1

            val_rows = predict_pyg(
                model,
                graphs,
                indices["val"],
                DataLoader,
                args.batch_size,
                device,
                target_mean,
                target_std,
            )
            val_true = np.asarray([x[1] for x in val_rows])
            val_pred = np.asarray([x[2] for x in val_rows])
            score = validation_selection_score(
                protocol, val_atom_counts, val_true, val_pred
            )
            history.append({
                "epoch": epoch,
                "train_loss": total_loss / max(batches, 1),
                "validation_selection_score": score,
                "validation_r2": safe_r2(val_true, val_pred),
                "validation_mae_eV": float(mean_absolute_error(val_true, val_pred)),
            })
            if score > best_score:
                best_score, best_epoch, stale_epochs = score, epoch, 0
                torch.save({
                    "model_state_dict": model.state_dict(),
                    "epoch": epoch,
                    "selection_score": score,
                    "target_mean": target_mean,
                    "target_std": target_std,
                    "seed": seed,
                    "protocol": protocol,
                    "official_repo_commit": official_commit,
                }, checkpoint_path)
            else:
                stale_epochs += 1
            if epoch % 10 == 0:
                print(
                    f"{model_key} {protocol} seed={seed} epoch={epoch} "
                    f"val_score={score:.5f} best={best_score:.5f}"
                )
            if stale_epochs >= args.pyg_patience:
                break

        pd.DataFrame(history).to_csv(history_path, index=False)
        checkpoint = torch_load_compatible(checkpoint_path, map_location=device)
        model.load_state_dict(checkpoint["model_state_dict"])

    metric_rows, prediction_rows = [], []
    for split_name in ("train", "val", "test"):
        rows = predict_pyg(model, graphs, indices[split_name], DataLoader,
                           args.batch_size, device, target_mean, target_std)
        true = [x[1] for x in rows]
        pred = [x[2] for x in rows]
        metric_rows.append(metric_row(model_key, protocol, seed, split_name, true, pred))
        for row_index, y_true, y_pred in rows:
            item = data[row_index]
            prediction_rows.append({
                "model": model_key, "protocol": protocol, "seed": seed,
                "split": split_name, "row_index": row_index,
                "sample_id": int(item["sample_id"]), "N": int(item["intended_N"]),
                "true": y_true, "pred": y_pred, "unit": TARGET_UNIT,
            })
    frame = pd.DataFrame(metric_rows)
    frame["best_epoch"] = best_epoch
    frame["validation_selection_score"] = best_score
    frame["official_repo_commit"] = official_commit
    frame.to_csv(metrics_path, index=False)
    pd.DataFrame(prediction_rows).to_csv(run_dir / "predictions.csv", index=False)
    return frame


def metrics_from_result_frame(frame: pd.DataFrame, model: str, protocol: str, seed: int) -> pd.DataFrame:
    rows = []
    for split_name, subset in frame.groupby("split", sort=False):
        rows.append(metric_row(model, protocol, seed, split_name,
                               subset["true"], subset["pred"]))
    return pd.DataFrame(rows)


def run_proposed(gap2, data, indices, protocol: str, seed: int,
                 run_dir: Path, args) -> pd.DataFrame:
    metrics_path = run_dir / "metrics.csv"
    completed = read_completed_metrics(metrics_path, "proposed", protocol, seed)
    if args.resume and completed is not None:
        print(f"Skipping completed run: proposed/{protocol}/seed_{seed}")
        return completed
    run_dir.mkdir(parents=True, exist_ok=True)
    old_seed, old_save = gap2.SEED, gap2.BASE_SAVE_DIR
    old_post = gap2.ENABLE_POSTPROCESSING
    try:
        gap2.SEED = seed
        gap2.BASE_SAVE_DIR = str(run_dir)
        gap2.ENABLE_POSTPROCESSING = False
        gap2.seed_everything(seed)
        groups = [gap2.split_for_atom_count(int(item["intended_N"])) for item in data]
        split_mode = "random" if protocol == "random" else "group_folder"
        results_path, _ = gap2.run_training_experiment(data, groups, split_mode=split_mode)
        frame = pd.read_csv(results_path)
        metrics = metrics_from_result_frame(frame, "proposed", protocol, seed)
        metrics.to_csv(metrics_path, index=False)
        experiment_dir = run_dir / f"mode_{split_mode}"
        write_manifest(data, indices, protocol, seed, experiment_dir / "dataset_manifest.csv")
        return metrics
    finally:
        gap2.SEED, gap2.BASE_SAVE_DIR = old_seed, old_save
        gap2.ENABLE_POSTPROCESSING = old_post
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()


def alignn_config(seed: int, counts: dict[str, int], output_dir: Path, epochs: int) -> dict[str, Any]:
    return {
        "dataset": "user_data", "target": "target", "atom_features": "cgcnn",
        "neighbor_strategy": "k-nearest", "id_tag": "jid", "dtype": "float32",
        "random_seed": seed, "classification_threshold": None,
        "n_train": counts["train"], "n_val": counts["val"], "n_test": counts["test"],
        "train_ratio": 0.8, "val_ratio": 0.1, "test_ratio": 0.1,
        "target_multiplication_factor": None, "epochs": epochs, "batch_size": 32,
        "weight_decay": 1e-5, "learning_rate": 0.001, "filename": f"gap_seed_{seed}",
        "warmup_steps": 2000, "criterion": "mse", "optimizer": "adamw",
        "scheduler": "onecycle", "pin_memory": False, "save_dataloader": False,
        "write_checkpoint": True, "write_predictions": True, "store_outputs": True,
        "progress": True, "log_tensorboard": False, "standard_scalar_and_pca": False,
        "use_canonize": True, "num_workers": 0, "cutoff": 8.0,
        "cutoff_extra": 3.0, "max_neighbors": 12, "keep_data_order": True,
        "normalize_graph_level_loss": False, "distributed": False,
        "data_parallel": False, "n_early_stopping": 70,
        "output_dir": str(output_dir), "use_lmdb": False,
        "model": {
            "name": "alignn_atomwise", "alignn_layers": 4, "gcn_layers": 4,
            "atom_input_features": 92, "edge_input_features": 80,
            "triplet_input_features": 40, "embedding_features": 64,
            "hidden_features": 256, "output_features": 1, "grad_multiplier": -1,
            "calculate_gradient": False, "atomwise_output_features": 0,
            "graphwise_weight": 1.0, "gradwise_weight": 0.0,
            "stresswise_weight": 0.0, "atomwise_weight": 0.0,
            "link": "identity", "zero_inflated": False, "classification": False,
            "force_mult_natoms": False, "energy_mult_natoms": False,
            "include_pos_deriv": False, "use_cutoff_function": False,
            "inner_cutoff": 3.0, "stress_multiplier": 1.0,
            "add_reverse_forces": True, "lg_on_fly": True,
            "batch_stress": True, "multiply_cutoff": False,
            "use_penalty": True, "extra_features": 0,
            "exponent": 5, "penalty_factor": 0.1, "penalty_threshold": 1.0,
        },
    }


def export_alignn(data, all_splits, output_dir: Path, epochs: int) -> None:
    shared = output_dir / "alignn_shared_xyz"
    shared.mkdir(parents=True, exist_ok=True)
    for index, item in enumerate(data):
        path = shared / f"row_{index:05d}_C{int(item['intended_N'])}_ID{int(item['sample_id'])}.xyz"
        if not path.exists():
            coords = np.asarray(item["coords"], dtype=float)
            with path.open("w", encoding="utf-8") as handle:
                handle.write(f"{len(coords)}\nC{item['intended_N']} ID={item['sample_id']}\n")
                for x, y, z in coords:
                    handle.write(f"C {x:.10f} {y:.10f} {z:.10f}\n")

    commands = []
    for (protocol, seed), indices in all_splits.items():
        run_dir = output_dir / "alignn_exports" / protocol / f"seed_{seed}"
        result_dir = run_dir / "results"
        run_dir.mkdir(parents=True, exist_ok=True)
        ordered = np.concatenate([indices["train"], indices["val"], indices["test"]])
        with (run_dir / "id_prop.csv").open("w", newline="", encoding="utf-8") as handle:
            writer = csv.writer(handle)
            for index in ordered:
                xyz = shared / f"row_{int(index):05d}_C{int(data[int(index)]['intended_N'])}_ID{int(data[int(index)]['sample_id'])}.xyz"
                writer.writerow([os.path.relpath(xyz, run_dir).replace("\\", "/"),
                                 float(data[int(index)]["y_target"])])
        counts = {name: len(values) for name, values in indices.items()}
        config_path = run_dir / "config.json"
        config_path.write_text(json.dumps(alignn_config(seed, counts, result_dir, epochs), indent=2),
                               encoding="utf-8")
        commands.append(
            f"train_alignn.py --root_dir '{run_dir}' --config_name '{config_path}' "
            f"--file_format xyz --output_dir '{result_dir}'"
        )
    command_file = output_dir / "run_alignn_commands.sh"
    command_file.write_text("#!/bin/bash\nset -e\n" + "\n".join(commands) + "\n", encoding="utf-8")


def aggregate_metrics(frames: list[pd.DataFrame], output_dir: Path,
                      expected_models, expected_protocols, expected_seeds) -> None:
    # Include metrics produced by earlier/resumed PBS jobs so the benchmark can
    # be split across models or protocols without losing the combined summary.
    completed = []
    for path in sorted((output_dir / "runs").glob("*/*/seed_*/metrics.csv")):
        completed.append(pd.read_csv(path))
    sources = completed if completed else frames
    if not sources:
        raise RuntimeError("No completed metric files were found.")
    all_metrics = pd.concat(sources, ignore_index=True)
    all_metrics = all_metrics.drop_duplicates(
        subset=["model", "protocol", "seed", "split"], keep="last"
    )
    all_metrics.to_csv(output_dir / "per_seed_metrics.csv", index=False)
    observed = {
        (str(row.model), str(row.protocol), int(row.seed), str(row.split))
        for row in all_metrics.itertuples(index=False)
    }
    expected = {
        (model, protocol, int(seed), split)
        for model in expected_models
        for protocol in expected_protocols
        for seed in expected_seeds
        for split in ("train", "val", "test")
    }
    missing = sorted(expected - observed)
    if missing:
        (output_dir / "incomplete_runs.json").write_text(
            json.dumps(missing, indent=2), encoding="utf-8"
        )
        raise RuntimeError(
            f"Benchmark is incomplete: {len(missing)} split-level metric rows are missing. "
            f"See {output_dir / 'incomplete_runs.json'}"
        )
    rows = []
    for (model, protocol, split), subset in all_metrics.groupby(["model", "protocol", "split"]):
        row = {"model": model, "protocol": protocol, "split": split,
               "n_seeds": int(subset["seed"].nunique()), "unit": TARGET_UNIT}
        for metric in ("r2", "mae", "rmse", "bias_pred_minus_true"):
            values = subset[metric].astype(float)
            row[f"{metric}_mean"] = float(values.mean())
            row[f"{metric}_std"] = float(values.std(ddof=1)) if len(values) > 1 else float("nan")
            row[f"{metric}_mean_pm_std"] = f"{values.mean():.6f} +/- {values.std(ddof=1):.6f}" if len(values) > 1 else f"{values.mean():.6f}"
        rows.append(row)
    summary = pd.DataFrame(rows).sort_values(["protocol", "split", "r2_mean"], ascending=[True, True, False])
    summary.to_csv(output_dir / "metrics_mean_std.csv", index=False)
    summary[summary["split"] == "test"].to_csv(output_dir / "test_metrics_mean_std.csv", index=False)
    print("\nFive-seed test summary")
    print(summary[summary["split"] == "test"][[
        "protocol", "model", "n_seeds", "r2_mean_pm_std",
        "mae_mean_pm_std", "rmse_mean_pm_std",
    ]].to_string(index=False))


def main() -> None:
    args = parse_args()
    project_dir = args.project_dir.resolve()
    os.chdir(project_dir)
    output_dir = args.output_dir
    if not output_dir.is_absolute():
        output_dir = project_dir / output_dir
    output_dir.mkdir(parents=True, exist_ok=True)

    gap2 = load_gap2(project_dir)
    csv_path = _resolve_under(project_dir, args.csv)
    geometry_root = _resolve_under(project_dir, args.geometry_root)
    cache_path = (
        _resolve_under(project_dir, args.cache)
        if args.cache is not None
        else (output_dir / "validated_raw_dataset_cache.pt").resolve()
    )
    data, dataset_fingerprint = load_or_build_raw_dataset(
        gap2, csv_path, geometry_root, cache_path,
        args.gap_unit, args.preprocess_workers, args.rebuild_cache,
    )
    print(
        f"Validated raw dataset: {csv_path}\n"
        f"Geometry root: {geometry_root}\n"
        f"Samples: {len(data)}; unit: {TARGET_UNIT}\n"
        f"Dataset fingerprint: {dataset_fingerprint}"
    )
    (output_dir / "dataset_provenance.json").write_text(json.dumps({
        "source_csv": str(csv_path),
        "geometry_root": str(geometry_root),
        "source_gap_unit": args.gap_unit,
        "training_target_unit": TARGET_UNIT,
        "sample_count": len(data),
        "dataset_fingerprint": dataset_fingerprint,
        "cache_path": str(cache_path),
    }, indent=2), encoding="utf-8")

    all_splits = {}
    for protocol in args.protocols:
        for seed in args.seeds:
            indices = split_indices(data, protocol, seed)
            all_splits[(protocol, seed)] = indices
            manifest_dir = output_dir / "manifests" / protocol
            manifest_dir.mkdir(parents=True, exist_ok=True)
            write_manifest(data, indices, protocol, seed, manifest_dir / f"seed_{seed}.csv")

    fullerene_graphs = matformer_graphs = None
    FullereneNet = Matformer = None
    official_commit = "not_used"
    if any(model in args.models for model in ("fullerenenet", "matformer")):
        official_commit = OFFICIAL_COMMIT
        FullereneNet = _load_embedded_module(
            "embedded_official_fullerenenet", _EMBEDDED_FULLERENENET
        ).FullereneNet
        Matformer = _load_embedded_module(
            "embedded_official_matformer", _EMBEDDED_MATFORMER
        ).Matformer
        fullerene_graphs, matformer_graphs = make_pyg_graphs(
            data, output_dir, dataset_fingerprint
        )
        (output_dir / "official_model_provenance.json").write_text(json.dumps({
            "repository": FULLERENENET_URL,
            "commit": official_commit,
            "license": "MIT",
            "source_mode": "embedded_in_standalone_script",
            "dataset_fingerprint": dataset_fingerprint,
            "fullerenenet_model_file": "<embedded_official_fullerenenet>",
            "matformer_model_file": "<embedded_official_matformer>",
        }, indent=2), encoding="utf-8")

    metric_frames = []
    for protocol in args.protocols:
        for seed in args.seeds:
            indices = all_splits[(protocol, seed)]
            print(f"\n===== protocol={protocol} seed={seed} =====")
            if "proposed" in args.models:
                metric_frames.append(run_proposed(
                    gap2, data, indices, protocol, seed,
                    output_dir / "runs" / "proposed" / protocol / f"seed_{seed}", args,
                ))
            if "fullerenenet" in args.models:
                metric_frames.append(run_official_pyg_model(
                    "fullerenenet", FullereneNet, fullerene_graphs, data, indices,
                    protocol, seed,
                    output_dir / "runs" / "fullerenenet" / protocol / f"seed_{seed}",
                    args, official_commit,
                ))
            if "matformer" in args.models:
                metric_frames.append(run_official_pyg_model(
                    "matformer", Matformer, matformer_graphs, data, indices,
                    protocol, seed,
                    output_dir / "runs" / "matformer" / protocol / f"seed_{seed}",
                    args, official_commit,
                ))

    if args.export_alignn:
        export_alignn(data, all_splits, output_dir, args.alignn_epochs)
    aggregate_metrics(metric_frames, output_dir, args.models, args.protocols, args.seeds)
    print(f"\nCompleted: {output_dir}")


if __name__ == "__main__":
    main()
